const body = $input.first().json.body || {};
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.deliveryReceipts)) {
  staticData.deliveryReceipts = [];
}
const receipt = {
  receiptId: `rcpt_${$execution.id}_${Date.now()}`,
  executionId: String($execution.id),
  conversationId: String(body.conversationId || ''),
  recipientEmail: String(body.recipientEmail || ''),
  idempotencyKey: String(body.idempotencyKey || ''),
  messagePreview: String(body.messageBody || '').slice(0, 120),
  gateApproved: true,
  dispatchedAt: new Date().toISOString()
};
staticData.deliveryReceipts.push(receipt);
// Cap retained receipts to last 200 to prevent unbounded growth
if (staticData.deliveryReceipts.length > 200) {
  staticData.deliveryReceipts = staticData.deliveryReceipts.slice(-200);
}
return [{ json: { ...receipt, status: 'dispatched', deliveredCount: staticData.deliveryReceipts.length } }];
